mapper.select:
SELECT COUNT(*)
FROM business_partner bp
WHERE bp.partner_id = #{customerId}
    AND bp.company_id = #{companyId}
    AND bp.customer_yn = 'Y'
    AND bp.use_yn = 'Y'

mapper.delete:
DELETE FROM sales_order_item
WHERE sales_order_id = #{salesOrderId}
AND EXISTS (
    SELECT 1
    FROM sales_order so
    WHERE so.sales_order_id = sales_order_item.sales_order_id
    AND so.company_id = #{companyId}
    AND so.order_status = 'DRAFT'
)
